try:
    from ast import literal_eval as _literal_eval
except ImportError:
    from compiler import parse
    from compiler.ast import Expression, Const, Tuple, List, Dict, Name, UnarySub

    def _is_const_literal(node):
        """Check if node is a constant literal."""
        return isinstance(node, Const) and isinstance(node.value, (basestring, int, float, long, complex))

    def _is_tuple(node):
        """Check if node is a tuple."""
        return isinstance(node, Tuple)

    def _is_list(node):
        """Check if node is a list."""
        return isinstance(node, List)

    def _is_dict(node):
        """Check if node is a dict."""
        return isinstance(node, Dict)

    def _is_name(node):
        """Check if node is a name."""
        return isinstance(node, Name)

    def _is_unary_sub(node):
        """Check if node is a unary subtraction."""
        return isinstance(node, UnarySub)

    def _convert_node(node, safe_names):
        """Recursively convert AST node to Python literal."""
        if _is_const_literal(node):
            return node.value
        if _is_tuple(node):
            return tuple(_convert_node(n, safe_names) for n in node.nodes)
        if _is_list(node):
            return list(_convert_node(n, safe_names) for n in node.nodes)
        if _is_dict(node):
            return { _convert_node(k, safe_names): _convert_node(v, safe_names) for k, v in node.items() }
        if _is_name(node):
            return safe_names.get(node.name)
        if _is_unary_sub(node):
            return -_convert_node(node.expr, safe_names)
        raise ValueError('malformed string')

    def _literal_eval(node_or_string):
        """
        Safely evaluate an expression node or a string containing a Python
        expression.  The string or node provided may only consist of the  following
        Python literal structures: strings, numbers, tuples, lists, dicts,  booleans,
        and None.
        """
        _safe_names = {'None': None, 'True': True, 'False': False}
        if isinstance(node_or_string, basestring):
            node_or_string = parse(node_or_string, mode='eval')
        if isinstance(node_or_string, Expression):
            node_or_string = node_or_string.node
        return _convert_node(node_or_string, _safe_names)

