protected void addPathFile(File pathComponent) throws IOException {
    if (!pathComponents.contains(pathComponent)) {
        pathComponents.addElement(pathComponent);
    }
    if (pathComponent.isDirectory()) {
        return;
    }
    String classpath = getCachedClasspath(pathComponent);
    if (!classpath.isEmpty()) {
        processClasspathEntries(pathComponent, classpath);
    }
}

private String getCachedClasspath(File pathComponent) throws IOException {
    String key = pathComponent.getAbsolutePath()
                + pathComponent.lastModified() + "-" + pathComponent.length();
    String cp = (String) pathMap.get(key);
    if (cp == null) {
        cp = readClasspathFromManifest(pathComponent);
        pathMap.put(key, cp);
    }
    return cp;
}

private String readClasspathFromManifest(File jarFile) throws IOException {
    JarFile jar = null;
    try {
        jar = new JarFile(jarFile);
        Manifest manifest = jar.getManifest();
        if (manifest == null) {
            return "";
        }
        String cp = manifest.getMainAttributes()
                .getValue(Attributes.Name.CLASS_PATH);
        return cp == null ? "" : cp;
    } finally {
        if (jar != null) {
            jar.close();
        }
    }
}

private void processClasspathEntries(File baseFile, String classpath) throws IOException {
    URL baseURL = FILE_UTILS.getFileURL(baseFile);
    StringTokenizer st = new StringTokenizer(classpath);
    while (st.hasMoreTokens()) {
        String element = st.nextToken();
        URL libURL = new URL(baseURL, element);
        if (!"file".equals(libURL.getProtocol())) {
            log("Skipping jar library " + element
                + " since only relative URLs are supported by this loader",
                Project.MSG_VERBOSE);
            continue;
        }
        String decodedPath = Locator.decodeUri(libURL.getFile());
        File libFile = new File(decodedPath);
        if (libFile.exists() && !isInPath(libFile)) {
            addPathFile(libFile);
        }
    }
}

