    /**
     * Check that all required attributes have been set and nothing
     * silly has been entered.
     *
     * @since Ant 1.5
     * @exception BuildException if an error occurs
     */
    protected void checkParameters() throws BuildException {
        if (src == null) {
            throw new BuildException("srcdir attribute must be set!",
                                     getLocation());
        }
        if (src.size() == 0) {
            throw new BuildException("srcdir attribute must be set!",
                                     getLocation());
        }

        if (destDir != null && !destDir.isDirectory()) {
            throw new BuildException("destination directory \""
                                     + destDir
                                     + "\" does not exist "
                                     + "or is not a directory", getLocation());
        }
        if (includeAntRuntime == null && getProject().getProperty("build.sysclasspath") == null) {
            log(getLocation() + "warning: 'includeantruntime' was not set, " +
                    "defaulting to build.sysclasspath=last; set to false for repeatable builds",
                    Project.MSG_WARN);
        }
    }

    /**
     * Perform the compilation.
     *
     * @since Ant 1.5
     */
    protected void compile() {
        String compilerImpl = getCompiler();

        if (compileList.length == 0) {
            return;
        }

        logCompilationStart();

        if (listFiles) {
            logFileList();
        }

        CompilerAdapter adapter = createCompilerAdapter(compilerImpl);
        adapter.setJavac(this);

        if (adapter.execute()) {
            handleSuccessfulCompilation();
        } else {
            handleFailedCompilation();
        }
    }

    /**
     * Logs the start of compilation with file count and destination.
     */
    private void logCompilationStart() {
        log("Compiling " + compileList.length + " source file"
            + (compileList.length == 1 ? "" : "s")
            + (destDir != null ? " to " + destDir : ""));
    }

    /**
     * Logs each source file that will be compiled.
     */
    private void logFileList() {
        for (File f : compileList) {
            log(f.getAbsolutePath());
        }
    }

    /**
     * Creates the appropriate CompilerAdapter.
     *
     * @param compilerImpl the compiler implementation name
     * @return a CompilerAdapter instance
     */
    private CompilerAdapter createCompilerAdapter(String compilerImpl) {
        return nestedAdapter != null ? nestedAdapter
                : CompilerAdapterFactory.getCompiler(compilerImpl, this,
                        createCompilerClasspath());
    }

    /**
     * Handles actions after a successful compilation.
     */
    private void handleSuccessfulCompilation() {
        if (createMissingPackageInfoClass) {
            try {
                generateMissingPackageInfoClasses(destDir != null
                        ? destDir
                        : getProject().resolveFile(src.list()[0]));
            } catch (IOException x) {
                throw new BuildException(x, getLocation());
            }
        }
    }

    /**
     * Handles actions after a failed compilation.
     */
    private void handleFailedCompilation() {
        this.taskSuccess = false;
        if (errorProperty != null) {
            getProject().setNewProperty(errorProperty, "true");
        }
        if (failOnError) {
            throw new BuildException(FAIL_MSG, getLocation());
        } else {
            log(FAIL_MSG, Project.MSG_ERR);
        }
    }

