    private void addStandardActions(ActionList actions) {
        int offset = 0;
        actions.add(new JSeparator());
        offset++;

        if (removeFromDiagram) {
            actions.add(ProjectActions.getInstance().getRemoveFromDiagramAction());
            offset++;
        }

        actions.add(new ActionDeleteModelElements());
        offset++;

        popupAddOffset = offset;
