        for (ArgoDiagram diagram : diagrams) {
            diagram.postLoad();
        }
        long endTime = System.currentTimeMillis();
        LOG.log(Level.FINE,
                "Diagram post load took {0} msec.", (endTime - startTime));

        Object model = getModel();

        LOG.log(Level.INFO, "Setting root model to {0}", model);

        setRoot(model);

        setSaveEnabled(true);
        uuidRefs = null;
    }

